from reader import address_of


def list_destinations(records):
    return [{"id": row["id"], "address": address_of(row)} for row in records]

def migrate_batch(records, limit):
    migrated = 0
    for row in records:
        if migrated >= limit:
            break
        if "destination" not in row:
            row["destination"] = {"address": row.pop("address")}
            migrated += 1
    return migrated

